import React, { useMemo, useState } from "react";
import styled from "styled-components";
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "framer-motion";
import { ArrowRight, Github, Mail } from "lucide-react";
import Section from "../../components/layout/Section";
import MagneticButton from "../../components/ui/MagneticButton";
import HitlDesk from "../../components/ui/HitlDesk";

const Stack = styled.div`
  display: flex;
  flex-direction: column;
  gap: 2.25rem;
`;

const Top = styled.div`
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 3rem;
  align-items: center;

  @media (max-width: 960px) {
    grid-template-columns: 1fr;
    gap: 1.75rem;
  }
`;

const Text = styled.div`
  display: flex;
  flex-direction: column;
  gap: 1rem;
`;

const Pulse = styled.span`
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: ${(p) => p.theme.colors.success};
  box-shadow: 0 0 0 4px ${(p) => p.theme.colors.success}33;
`;

const Name = styled(motion.h1)`
  font-family: ${(p) => p.theme.typography.fontDisplay};
  font-size: ${(p) => p.theme.typography.fluidH1};
  font-weight: 800;
  letter-spacing: -0.025em;
  line-height: 1.02;
  margin: 0;
  color: ${(p) => p.theme.colors.text};
`;

const Role = styled(motion.p)`
  margin: 0;
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: ${(p) => p.theme.colors.textSecondary};

  strong {
    color: ${(p) => p.theme.colors.text};
    font-weight: 600;
  }
`;

const Description = styled(motion.p)`
  font-size: ${(p) => p.theme.typography.fluidBody};
  color: ${(p) => p.theme.colors.textSecondary};
  line-height: 1.78;
  margin: 0.15rem 0 0.25rem;
  max-width: 56ch;

  strong {
    color: ${(p) => p.theme.colors.text};
    font-weight: 700;
  }
`;

const Actions = styled(motion.div)`
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  align-items: center;
`;

const Socials = styled(motion.div)`
  display: flex;
  gap: 0.55rem;
`;

const Social = styled.a`
  width: 40px;
  height: 40px;
  border: 1px solid ${(p) => p.theme.colors.borderStrong};
  background: ${(p) => p.theme.colors.surface};
  color: ${(p) => p.theme.colors.text};
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;

  &:hover {
    border-color: ${(p) => p.theme.colors.primary};
    color: ${(p) => p.theme.colors.primary};
  }
`;

const ProfileWrap = styled.div`
  display: flex;
  justify-content: center;
`;

const ProfileCard = styled(motion.div)`
  position: relative;
  width: min(320px, 78vw);
  aspect-ratio: 1 / 1;
  background: ${(p) => p.theme.colors.surface};
  border: 1px solid ${(p) => p.theme.colors.borderStrong};
  box-shadow: ${(p) => p.theme.shadows.cardHover};
  overflow: hidden;
`;

const ProfileGlow = styled.div`
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    140px 140px at var(--mx, 50%) var(--my, 50%),
    ${(p) => p.theme.colors.primary}40,
    transparent 70%
  );
  mix-blend-mode: screen;
  z-index: 2;
`;

const ProfileInner = styled(motion.div)`
  position: absolute;
  inset: 0;
`;

const ProfileImg = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
`;

const ProfileInitials = styled.div`
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: ${(p) => p.theme.colors.gradient};
  color: #fff;
  font-family: ${(p) => p.theme.typography.fontDisplay};
  font-size: clamp(3.5rem, 9vw, 5rem);
  font-weight: 800;
`;

const Badge = styled.div`
  position: absolute;
  left: 14px;
  bottom: 14px;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.35rem 0.65rem;
  background: ${(p) =>
    `color-mix(in srgb, ${p.theme.colors.backgroundElevated} 82%, transparent)`};
  border: 1px solid ${(p) => p.theme.colors.borderStrong};
  backdrop-filter: blur(6px);
  color: ${(p) => p.theme.colors.text};
  font-size: 0.78rem;
  font-weight: 600;
`;

type Props = {
  displayName: string;
  githubUrl: string;
  email: string;
  onPrimary: () => void;
  onLab: () => void;
};

const HeroSection: React.FC<Props> = ({
  displayName,
  githubUrl,
  email,
  onPrimary,
  onLab,
}) => {
  const reduced = useReducedMotion();
  const [imgFailed, setImgFailed] = useState(false);
  const profileSrc = `${process.env.PUBLIC_URL || ""}/profile.jpg`;

  const initials = useMemo(() => {
    const parts = displayName.trim().split(/\s+/);
    return (
      (parts[0]?.charAt(0) ?? "?") + (parts[1]?.charAt(0) ?? "")
    ).toUpperCase();
  }, [displayName]);

  const rx = useMotionValue(0);
  const ry = useMotionValue(0);
  const springRX = useSpring(rx, { stiffness: 120, damping: 14 });
  const springRY = useSpring(ry, { stiffness: 120, damping: 14 });
  const rotateX = useTransform(springRX, [-1, 1], ["8deg", "-8deg"]);
  const rotateY = useTransform(springRY, [-1, 1], ["-8deg", "8deg"]);

  const onMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (reduced) return;
    const r = e.currentTarget.getBoundingClientRect();
    const nx = (e.clientX - r.left) / r.width;
    const ny = (e.clientY - r.top) / r.height;
    rx.set(ny * 2 - 1);
    ry.set(nx * 2 - 1);
    e.currentTarget.style.setProperty("--mx", `${nx * 100}%`);
    e.currentTarget.style.setProperty("--my", `${ny * 100}%`);
  };

  return (
    <Section id="home" fullHeight glow>
      <Stack>
        <Top>
          <Text>
            <Name
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.05 }}
            >
              {displayName}
            </Name>
            <Role
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
            >
              백엔드 개발자, 생성형 AI 구축
            </Role>
            <Description
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.16 }}
            >
              FastAPI와 Spring Boot로 생성형 AI를 고객 환경에 올립니다.
              결제 성공 후 주문이 비던 일을 Datadog, API 로그, DB를 같은
              request로 맞춰 닫았습니다. 그래서 호출마다 추적이 남게 짭니다.
              추론은 vLLM, 에이전트는 DAG로 나눕니다. 가드레일이 막으면 LLM을
              부르지 않습니다.
              <br />
              <br />
              민원 화면은 AI 초안과 담당자 확정을 나눕니다. 아래 콘솔에서 동작을
              확인할 수 있습니다.
            </Description>
            <Actions
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.22 }}
            >
              <MagneticButton variant="primary" onClick={onPrimary}>
                프로젝트 보기 <ArrowRight size={16} />
              </MagneticButton>
              <MagneticButton variant="ghost" strength={8} onClick={onLab}>
                실험 보기
              </MagneticButton>
              <MagneticButton
                variant="ghost"
                strength={8}
                onClick={() => {
                  window.location.href = `mailto:${email}`;
                }}
              >
                <Mail size={16} /> 이메일
              </MagneticButton>
            </Actions>
            <Socials
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.3 }}
            >
              <Social
                href={githubUrl}
                target="_blank"
                rel="noopener noreferrer"
                aria-label="GitHub"
              >
                <Github size={16} />
              </Social>
              <Social href={`mailto:${email}`} aria-label="Email">
                <Mail size={16} />
              </Social>
            </Socials>
          </Text>

          <ProfileWrap>
            <ProfileCard
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.18, duration: 0.55 }}
              onMouseMove={onMove}
              onMouseLeave={() => {
                rx.set(0);
                ry.set(0);
              }}
              style={{ transformStyle: "preserve-3d" }}
            >
              <ProfileGlow />
              <ProfileInner style={{ rotateX, rotateY }}>
                {!imgFailed ? (
                  <ProfileImg
                    src={profileSrc}
                    alt={`${displayName} 프로필`}
                    onError={() => setImgFailed(true)}
                  />
                ) : (
                  <ProfileInitials>{initials || "EJ"}</ProfileInitials>
                )}
              </ProfileInner>
              <Badge>
                <Pulse /> 고객 환경에 올립니다
              </Badge>
            </ProfileCard>
          </ProfileWrap>
        </Top>

        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.28, duration: 0.5 }}
        >
          <HitlDesk />
        </motion.div>
      </Stack>
    </Section>
  );
};

export default HeroSection;
